<script>
$(function(){var $type=$('#disposal-type'),$proceeds=$('#disposal-proceeds'),$sale=$('#sale-reference-field'),$writeoff=$('#writeoff-references'),$ref=$('[name=proceeds_reference]'),$marker=$('#sale-reference-required');function sync(){var sale=$type.val()==='SALE';$sale.toggleClass('d-none',!sale);$writeoff.toggleClass('d-none',sale);var required=sale&&Number($proceeds.val()||0)>0;$ref.prop('required',required);$marker.toggleClass('d-none',!required);if(!sale){$ref.val('').prop('required',false);}else{$('[name=count_reference],[name=investigation_reference],[name=override_reason]').val('');}}$type.on('change',sync);$proceeds.on('input change',sync);sync();window.erpInitSelect2('.js-disposal-assets',{placeholder:'ค้นหาเลขที่หรือชื่อสินทรัพย์',allowClear:true,ajax:{url:'{{ route('asset.disposals.assets') }}',delay:250,data:function(p){return{q:p.term||'',page:p.page||1};},processResults:function(d){return d;}}});$('[data-bs-toggle="tooltip"]').each(function(){new bootstrap.Tooltip(this);});window.erpAjaxForm({form:'#disposal-form',redirect:true});});
</script>
